1|// Now-playing line. Pure: one understated line plus the full credit for
2|// the tooltip. Missing parts drop out with no stray separators.
3|import type { Track } from "./music-types";
4|
5|export interface NowPlaying {
6|  line: string;
7|  full: string;
8|}
9|
10|export function nowPlaying(
11|  track: ({ title: string } & Partial<Pick<Track, "composer" | "artist" | "attribution" | "license">>) | null,
12|  soundtrackCredit: string | null | undefined,
13|): NowPlaying | null {
14|  if (track === null) return null;
15|  const who = track.composer ?? track.artist ?? null;
16|  const source = track.attribution ?? soundtrackCredit ?? null;
17|  const line = [track.title, who, source].filter((p): p is string => p !== null).join(" · ");
18|  const full = [...[track.title, who, source], track.license ?? null]
19|    .filter((p): p is string => p !== null)
20|    .join(" · ");
21|  return { line, full };
