3|import { useEffect, useMemo, useRef, useState } from "react";
4|import { useRouter } from "next/navigation";
5|import { buildNavIndex, navReducer } from "@/core/reader";
6|import type { NavAction, SceneView } from "@/core/reader";
7|
8|export interface ChapterJump {
9|  ch: number;
10|  title: string;
11|  firstSceneId: string;
12|}
13|
14|// One-shot entry intent: set just before pushing the previous scene
15|// route, so the new page opens on its last sub-page. Client memory only,
16|// never the URL, so prerendered pages stay static and a direct URL load
17|// always starts at page 0.
18|let enterAtEnd = false;
19|
20|// Set on every in-app scene push. The heading takes focus only when this
21|// is set, so first load shows no focus ring.
22|let hasNavigated = false;
23|
24|// One scene view: sub-pages, keys, buttons, progress, chapter jump.
25|// Sub-page moves stay in client state; scene moves push a new route.
26|export function ScenePage({
27|  view,
28|  chapters,
29|  views,
30|}: {
31|  view: SceneView;
32|  chapters: ChapterJump[];
33|  views: { sceneId: string; pages: number }[];
34|}) {
35|  const router = useRouter();
36|  const index = useMemo(() => buildNavIndex(views), [views]);
37|  const lastPage = view.pages.length - 1;
38|  const [page, setPage] = useState(() => {
39|    if (enterAtEnd) {
40|      enterAtEnd = false;
41|      return lastPage;
42|    }
43|    return 0;
44|  });
45|  const headingRef = useRef<HTMLHeadingElement>(null);
46|  const sub = view.pages[page] ?? view.pages[0];
47|  const atStart = view.prevSceneId === null && page === 0;
48|  const atBookEnd = view.nextSceneId === null && page === lastPage;
49|
50|  // Every pager move runs through navReducer; a new scene id means a
51|  // route push, a same-scene result means a client sub-page move.
52|  function move(action: NavAction) {
53|    const next = navReducer({ sceneId: view.sceneId, page }, action, index);
54|    if (next.sceneId !== view.sceneId) {
55|      hasNavigated = true;
56|      if (next.page > 0) enterAtEnd = true;
57|      router.push(`/leer/${next.sceneId}`);
58|      return;
59|    }
60|    if (next.page !== page) {
61|      setPage(next.page);
62|      window.scrollTo(0, 0);
63|    }
64|  }
65|
66|  function goNext() {
67|    move({ kind: "next" });
68|  }
69|
70|  function goPrev() {
71|    move({ kind: "prev" });
72|  }
73|
74|  // Scene entry resets orientation; sub-page moves keep the heading.
75|  useEffect(() => {
76|    if (hasNavigated) headingRef.current?.focus();
77|    window.scrollTo(0, 0);
78|  }, [view.sceneId]);
79|
80|  useEffect(() => {
81|    const onKey = (event: KeyboardEvent) => {
82|      if (event.metaKey || event.ctrlKey || event.altKey) return;
83|      const target = event.target as HTMLElement | null;
84|      if (
85|        target &&
86|        (target.tagName === "INPUT" ||
87|          target.tagName === "SELECT" ||
88|          target.tagName === "TEXTAREA" ||
89|          target.isContentEditable)
90|      ) {
91|        return;
92|      }
93|      if (event.key === "ArrowRight") {
94|        event.preventDefault();
95|        goNext();
96|      } else if (event.key === "ArrowLeft") {
97|        event.preventDefault();
98|        goPrev();
99|      }
100|    };
101|    window.addEventListener("keydown", onKey);
102|    return () => window.removeEventListener("keydown", onKey);
103|  }, [page, view.sceneId, index, router]);
104|
105|  function jumpChapter(ch: number) {
106|    const found = chapters.find((c) => c.ch === ch);
107|    if (found && found.firstSceneId !== view.sceneId) move({ kind: "goto", sceneId: found.firstSceneId });
108|  }
109|
110|  return (
111|    <article aria-labelledby="scene-heading">
112|      <div className="scene-view" key={`${view.sceneId}:${page}`}>
113|        <p className="scene-progress">
114|          {`Chapter ${view.ch} · ${view.chapterTitle} · Scene ${view.k} of ${view.n}${view.pages.length > 1 ? ` · Page ${page + 1} of ${view.pages.length}` : ""}`}
115|        </p>
116|        <h2 id="scene-heading" ref={headingRef} tabIndex={-1}>
117|          {view.title}
118|        </h2>
119|        {sub?.paragraphs.map((p) => (
120|          <p key={p.id} id={p.id} data-n={p.n}>
121|            {p.text}
122|          </p>
123|        ))}
124|      </div>
125|      <nav className="scene-nav" aria-label="Scenes">
126|        <button type="button" onClick={goPrev} disabled={atStart} aria-label="Previous">
127|          Previous
128|        </button>
129|        <button type="button" onClick={goNext} disabled={atBookEnd} aria-label="Next">
130|          Next
131|        </button>
132|        <label className="scene-jump">
